/// The design system's colour tokens. A skin gives each one a value; it never adds a role or moves the accent to another one.
enum ColorToken: String, CaseIterable, Sendable {
    case surface0 = "surface-0"
    case surface1 = "surface-1"
    case surface2 = "surface-2"
    case display
    case displayInk = "display-ink"
    case displayMuted = "display-muted"
    case displayTrack = "display-track"
    case displayEdge = "display-edge"
    case ink
    case inkMuted = "ink-muted"
    case line
    case keyFace = "key-face"
    case keyMode = "key-mode"
    case keyPlay = "key-play"
    case keyInk = "key-ink"
    case keyModeInk = "key-mode-ink"
    case keyPlayPressed = "key-play-pressed"
    case keyFacePressed = "key-face-pressed"
    case keyModePressed = "key-mode-pressed"
    case track
    case fill
    case led
    case ledOff = "led-off"
    case signal
    case danger
    case focus
}

